import { z } from 'zod';
import type { Detection, NewsItem, PageSignals } from './types';
import type { SellerProfile } from './settings';
import type { HiringSignals } from './hiring';
import { findCompetitors } from './competitors';

/**
 * Structured brief generated by the LLM (step 5).
 * Validated with Zod; the model gets one retry on invalid JSON.
 */

/**
 * Grounding basis shared by talking points and the overview:
 * - 'news': drawn from a cited headline (sourceRefs / overviewRefs)
 * - 'stack': drawn from a detected technology (stackRefs / overviewStackRefs)
 * - 'site': drawn from the company's own website text
 * - 'hiring': drawn from open job postings
 * - 'inference': the model's inference, not directly grounded
 */
export const BasisSchema = z.enum(['news', 'stack', 'site', 'hiring', 'inference']);

export const TalkingPointSchema = z.object({
  point: z.string().min(1),
  /** Indexes into the news array passed to the prompt. */
  sourceRefs: z.array(z.number().int().nonnegative()),
  /** Indexes into the detections array. Grounds stack-based points. */
  stackRefs: z.array(z.number().int().nonnegative()).default([]),
  /** Grounding basis for this point (see BasisSchema). */
  basis: BasisSchema.default('news'),
});

/**
 * A grounded watch-out about the prospect (layoffs, churn signals,
 * tech mismatch, a hiring freeze). Mirrors TalkingPointSchema's
 * shape exactly; only the basis default differs — 'inference',
 * because risks are primarily reasoned watch-outs.
 */
export const RiskSchema = z.object({
  point: z.string().min(1),
  /** Indexes into the news array passed to the prompt. */
  sourceRefs: z.array(z.number().int().nonnegative()),
  /** Indexes into the detections array. Grounds stack-based risks. */
  stackRefs: z.array(z.number().int().nonnegative()).default([]),
  /** Grounding basis for this risk (see BasisSchema). */
  basis: BasisSchema.default('inference'),
});

/**
 * A grounded positive opening at the prospect (expansion, funding,
 * new leadership, a hiring surge, a stack change creating a fit).
 * Mirrors TalkingPointSchema/RiskSchema exactly; basis defaults to
 * 'news' — opportunities are primarily headline/hiring-driven
 * openings.
 */
export const OpportunitySchema = z.object({
  point: z.string().min(1),
  /** Indexes into the news array passed to the prompt. */
  sourceRefs: z.array(z.number().int().nonnegative()),
  /** Indexes into the detections array. Grounds stack-based openings. */
  stackRefs: z.array(z.number().int().nonnegative()).default([]),
  /** Grounding basis for this opening (see BasisSchema). */
  basis: BasisSchema.default('news'),
});

/** The schema version newly generated briefs are stamped with. */
export const CURRENT_BRIEF_SCHEMA_VERSION = 2 as const;

export const BriefSchema = z.object({
  /**
   * Schema version of this brief payload (v0.5): 1 is the original
   * shape, 2 the current one. Payloads written before the field
   * existed carry no schemaVersion and read as version 1 (the
   * default); any other value fails validation. The generation
   * path stamps new briefs with CURRENT_BRIEF_SCHEMA_VERSION.
   */
  schemaVersion: z.union([z.literal(1), z.literal(2)]).default(1),
  overview: z.string().min(1),
  /** News indexes cited by the overview. */
  overviewRefs: z.array(z.number().int().nonnegative()).default([]),
  /** Detection indexes cited by the overview (parity with talking-point stackRefs). */
  overviewStackRefs: z.array(z.number().int().nonnegative()).default([]),
  /**
   * Grounding basis for the overview (see BasisSchema). Default
   * 'site': the overview primarily summarises the company's own
   * website text. Defaulted so v1 and existing v2 payloads without
   * the field parse exactly as before.
   */
  overviewBasis: BasisSchema.default('site'),
  talkingPoints: z.array(TalkingPointSchema).min(1).max(8),
  /**
   * Grounded watch-outs about the prospect. Defaulted (empty) so
   * v1 and existing v2 payloads without the section parse exactly
   * as before.
   */
  risks: z.array(RiskSchema).default([]),
  /**
   * Grounded positive openings at the prospect. Defaulted (empty)
   * so v1 and existing v2 payloads without the section parse
   * exactly as before.
   */
  opportunities: z.array(OpportunitySchema).default([]),
});

export type Brief = z.infer<typeof BriefSchema>;

/**
 * JSON Schema for the Anthropic structured-output request
 * (output_config.format — the current documented mechanism, per
 * https://docs.claude.com/en/docs/build-with-claude/structured-outputs),
 * DERIVED from BriefSchema so the API-side schema can never drift
 * from the validation schema: z.toJSONSchema renders the zod
 * schema, then the transform strips the constraint keywords
 * Anthropic's structured-output grammar does not support
 * (minLength/maxLength, minItems/maxItems, minimum/maximum,
 * defaults, the $schema marker — the documented SDK helpers do the
 * same removal) and pins additionalProperties: false on every
 * object, as the API requires. Local validation
 * (validateBriefResponse) still enforces every stripped constraint
 * — defence in depth.
 */
const UNSUPPORTED_SCHEMA_KEYS = new Set([
  '$schema',
  'default',
  'minLength',
  'maxLength',
  'minItems',
  'maxItems',
  'minimum',
  'maximum',
]);

function toStructuredOutputSchema(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(toStructuredOutputSchema);
  if (typeof node !== 'object' || node === null) return node;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(node)) {
    if (UNSUPPORTED_SCHEMA_KEYS.has(key)) continue;
    out[key] = toStructuredOutputSchema(value);
  }
  if (out.type === 'object') out.additionalProperties = false;
  return out;
}

export const BRIEF_JSON_SCHEMA = toStructuredOutputSchema(
  z.toJSONSchema(BriefSchema),
) as Record<string, unknown>;

const ANTHROPIC_URL = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_VERSION = '2023-06-01';

/**
 * Rough token estimate: ~4 characters per token. This is the
 * measurement convention the repo's token constants (here and the
 * batch cost estimates in batch.ts) are derived on.
 */
export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

/**
 * Output ceiling for one brief generation (v0.5 final step),
 * DERIVED from the current brief shape: a maximal brief — 8
 * talking points (the schema cap), 8 risks, 8 opportunities,
 * 235-character points, 10 refs per ref array, a 604-character
 * overview — serialises to 8,793 characters ≈ 2,199 estimated
 * tokens. 4096 holds that with ~1.9x headroom. A unit test pins a
 * fixture of that maximal brief against this constant, so a
 * future section that outgrows the ceiling fails the suite
 * instead of truncating as a silent max_tokens partial.
 */
export const BRIEF_MAX_OUTPUT_TOKENS = 4096;

/**
 * Combined per-generation ceiling: estimated prompt tokens +
 * BRIEF_MAX_OUTPUT_TOKENS must not exceed this. Measured prompts
 * run ~650 (minimal) to ~2,100 (every section populated)
 * estimated tokens, so a prompt estimate over ~4,100 tokens means
 * the assembled material is anomalous; generation then fails
 * BEFORE any API call with the named 'prompt-over-ceiling'
 * failure instead of sending an oversized request or truncating
 * fetched material behind the caller's back.
 */
export const BRIEF_MAX_TOTAL_TOKENS = 8192;

export function buildPrompt(
  signals: PageSignals,
  detections: Detection[],
  news: NewsItem[],
  seller: SellerProfile | null,
  hiring: HiringSignals | null = null,
): string {
  const stack = detections
    .map(
      (d, i) =>
        `[S${i}] ${d.name} (${d.category}, ${d.confidence} confidence): ${d.evidence.join('; ')}`,
    )
    .join('\n');

  const headlines = news
    .map(
      (n, i) =>
        `[${i}] "${n.title}" — ${n.source ?? 'unknown'}${n.pubDate ? ` (${n.pubDate.slice(0, 10)})` : ''}`,
    )
    .join('\n');

  const hiringSection = hiring
    ? `HIRING SIGNALS (from the company's public job board, ${hiring.board})
Open roles: ${hiring.totalRoles}
Top departments: ${hiring.departments.map((d) => `${d.name} (${d.count})`).join(', ') || '(unknown)'}
Sample roles:
${hiring.topRoles.map((r) => `- ${r.title}${r.department ? ` (${r.department})` : ''}${r.location ? ` - ${r.location}` : ''}`).join('\n')}

`
    : '';

  const competitorMatches = seller ? findCompetitors(detections, seller.competitors) : [];
  const competitorSection =
    competitorMatches.length > 0
      ? `COMPETITOR ALERT: This prospect already uses ${competitorMatches
          .map((m) => m.detection.name)
          .join(
            ', ',
          )}, which competes with what the seller offers. This is a DISPLACEMENT opportunity: at least one talking point must acknowledge the incumbent and angle on switching (migration ease, gaps in the incumbent, total cost). Do not pitch as if the category were empty.

`
      : '';

  const sellerSection =
    seller && seller.whatYouSell.trim()
      ? `SELLER CONTEXT (the rep using this tool)
What they sell: ${seller.whatYouSell}
Ideal customer: ${seller.idealCustomer || '(not specified)'}
Value props:
${seller.valueProps.map((v, i) => `${i + 1}. ${v}`).join('\n') || '(none listed)'}

`
      : '';

  const talkingPointRule =
    seller && seller.whatYouSell.trim()
      ? `- Every talking point must connect one of the seller's value props to a specific observed signal (tech stack item, headline, or site fact). Lead with the prospect's situation, then the relevant value prop.`
      : `- Every talking point must reference at least one headline by its [index] in sourceRefs.`;

  return `You are writing a one-page sales prospect brief for the company behind this website.

WEBSITE
URL: ${signals.dom.url}
Title: ${signals.dom.title}
Description: ${signals.dom.metaDescription ?? '(none)'}
Visible text (truncated): ${signals.dom.visibleText.slice(0, 1500)}

DETECTED TECH STACK (deterministic, from page signals)
${stack || '(none detected)'}

RECENT NEWS HEADLINES
${headlines || '(none found)'}

${hiringSection}${competitorSection}${sellerSection}RULES
- Only state facts supported by the website text, tech stack, or headlines above. Do NOT invent funding rounds, employee counts, revenue, or partnerships.
- GROUNDING: For each talking point, set "basis" to where the claim comes from: "news" (a headline - include its index in sourceRefs), "stack" (a detected technology - include its [S#] index in stackRefs), "site" (the company's own website text), "hiring" (an open role or hiring pattern from HIRING SIGNALS), or "inference" (your own reasoning, not directly grounded). Never claim a basis you cannot support.
- RISKS: List watch-outs about this prospect that the material above actually supports (e.g. layoffs, a hiring freeze, churn signals, a tech mismatch) in risks. For each risk, cite supporting headline indexes in sourceRefs and supporting tech-stack [S#] indexes in stackRefs, and set basis honestly using the same basis definitions as for talking points. If nothing in the material supports a risk, return an empty risks array rather than inventing one.
- OPPORTUNITIES: List positive openings at this prospect that the material above actually supports (e.g. expansion, funding, new leadership, a hiring surge, a tech-stack change creating a fit) in opportunities. For each opportunity, cite supporting headline indexes in sourceRefs and supporting tech-stack [S#] indexes in stackRefs, and set basis honestly using the same basis definitions as for talking points. If nothing in the material supports an opening, return an empty opportunities array rather than inventing one.
- If a signal is absent (no news, no relevant tech), leave the point out rather than inventing one. Prefer "not found" over guessing.
- The overview may only cite headlines or detected technologies that actually support it; put supporting headline indexes in overviewRefs and supporting tech-stack [S#] indexes in overviewStackRefs (both empty if none apply), and set overviewBasis to where the overview's claims mainly come from, using the same basis definitions as for talking points.
- If the headlines don't support a claim, don't make it.
${talkingPointRule}
- Keep the overview to 3-4 sentences. Keep each talking point to 1-2 sentences.`;
}

/* ------------------------------------------------------------------ */
/* Schema validation (v0.4 step 2)                                     */
/* ------------------------------------------------------------------ */

/**
 * Result of validating one raw model response against the Brief
 * schema. `failures` holds stable, named reason codes (not Zod's
 * prose), so callers and tests can check exactly what went wrong.
 */
export interface BriefValidationResult {
  valid: boolean;
  /** The parsed brief when valid; null otherwise. */
  brief: Brief | null;
  /** Named failure reasons, in check order, de-duplicated. */
  failures: string[];
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isRefArray(value: unknown): boolean {
  return (
    Array.isArray(value) &&
    value.every((ref) => typeof ref === 'number' && Number.isInteger(ref) && ref >= 0)
  );
}

/**
 * Validate a raw brief response (the model's text) against
 * BriefSchema, naming each failure mode. Pure: no I/O. The named
 * reasons cover the brief's own fields first (missing/empty/wrong
 * type, ref shape); anything the schema still rejects falls back to
 * `schema:<path>:<zod code>`.
 */
export function validateBriefResponse(raw: string): BriefValidationResult {
  // Strip markdown code fences if the model wrapped the JSON.
  const cleaned = raw
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  let parsed: unknown;
  try {
    parsed = JSON.parse(cleaned);
  } catch {
    return { valid: false, brief: null, failures: ['invalid-json'] };
  }

  if (!isPlainObject(parsed)) {
    return { valid: false, brief: null, failures: ['not-an-object'] };
  }

  const failures: string[] = [];
  const push = (reason: string) => {
    if (!failures.includes(reason)) failures.push(reason);
  };

  if (
    parsed.schemaVersion !== undefined &&
    parsed.schemaVersion !== 1 &&
    parsed.schemaVersion !== 2
  ) {
    push('invalid-schema-version');
  }

  if (parsed.overview === undefined) push('missing-overview');
  else if (typeof parsed.overview !== 'string') push('overview-wrong-type');
  else if (parsed.overview.length === 0) push('empty-overview');

  if (parsed.overviewRefs !== undefined && !isRefArray(parsed.overviewRefs)) {
    push('invalid-ref-shape:overviewRefs');
  }

  if (parsed.overviewStackRefs !== undefined && !isRefArray(parsed.overviewStackRefs)) {
    push('invalid-ref-shape:overviewStackRefs');
  }

  if (parsed.talkingPoints === undefined) push('missing-talking-points');
  else if (!Array.isArray(parsed.talkingPoints)) push('talking-points-wrong-type');
  else {
    if (parsed.talkingPoints.length === 0) push('empty-talking-points');
    if (parsed.talkingPoints.length > 8) push('too-many-talking-points');
    for (const point of parsed.talkingPoints) {
      if (!isPlainObject(point)) {
        push('talking-point-wrong-type');
        continue;
      }
      if (point.point === undefined) push('missing-talking-point-text');
      else if (typeof point.point !== 'string') push('talking-point-text-wrong-type');
      else if (point.point.length === 0) push('empty-talking-point-text');
      if (point.sourceRefs === undefined) push('missing-source-refs');
      else if (!isRefArray(point.sourceRefs)) push('invalid-ref-shape:sourceRefs');
      if (point.stackRefs !== undefined && !isRefArray(point.stackRefs)) {
        push('invalid-ref-shape:stackRefs');
      }
    }
  }

  // Risks (v0.5): only the ref shapes get named checks, in the
  // same style as the talking-point checks; any other malformation
  // (non-array, bad basis, empty text) falls through to the schema
  // path below, as with overviewBasis.
  if (Array.isArray(parsed.risks)) {
    for (const risk of parsed.risks) {
      if (!isPlainObject(risk)) continue;
      if (risk.sourceRefs !== undefined && !isRefArray(risk.sourceRefs)) {
        push('invalid-ref-shape:risks.sourceRefs');
      }
      if (risk.stackRefs !== undefined && !isRefArray(risk.stackRefs)) {
        push('invalid-ref-shape:risks.stackRefs');
      }
    }
  }

  // Opportunities (v0.5): same named ref-shape checks as risks.
  if (Array.isArray(parsed.opportunities)) {
    for (const opportunity of parsed.opportunities) {
      if (!isPlainObject(opportunity)) continue;
      if (opportunity.sourceRefs !== undefined && !isRefArray(opportunity.sourceRefs)) {
        push('invalid-ref-shape:opportunities.sourceRefs');
      }
      if (opportunity.stackRefs !== undefined && !isRefArray(opportunity.stackRefs)) {
        push('invalid-ref-shape:opportunities.stackRefs');
      }
    }
  }

  if (failures.length > 0) return { valid: false, brief: null, failures };

  const result = BriefSchema.safeParse(parsed);
  if (!result.success) {
    for (const issue of result.error.issues) {
      push(`schema:${issue.path.join('.') || 'root'}:${issue.code}`);
    }
    return { valid: false, brief: null, failures };
  }
  return { valid: true, brief: result.data, failures: [] };
}

/**
 * One generation run's observable signals (v0.4 step 2): the brief,
 * the Anthropic stop_reason of the response that produced it, and
 * that response's schema-validation result — the inputs
 * classifyRunOutcome (run-outcome.ts) needs, surfaced instead of
 * discarded.
 */
export interface BriefGeneration {
  brief: Brief;
  stopReason: string | null;
  validation: BriefValidationResult;
}

interface AnthropicResponse {
  text: string;
  stopReason: string | null;
}

async function callAnthropic(
  apiKey: string,
  model: string,
  prompt: string,
): Promise<AnthropicResponse> {
  const res = await fetch(ANTHROPIC_URL, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': ANTHROPIC_VERSION,
      'anthropic-dangerous-direct-browser-access': 'true',
    },
    body: JSON.stringify({
      model,
      max_tokens: BRIEF_MAX_OUTPUT_TOKENS,
      messages: [{ role: 'user', content: prompt }],
      // Structured output (JSON outputs): the API constrains the
      // response to the Brief JSON schema. The response still
      // arrives as a text block and is validated locally as before.
      output_config: {
        format: { type: 'json_schema', schema: BRIEF_JSON_SCHEMA },
      },
    }),
  });
  if (!res.ok) {
    const body = await res.text().catch(() => '');
    throw new Error(`Anthropic API error: HTTP ${res.status} ${body.slice(0, 200)}`);
  }
  const data = (await res.json()) as {
    content?: Array<{ type?: string; text?: string }>;
    stop_reason?: string | null;
  };
  const text = data.content?.find((b) => b.type === 'text')?.text;
  if (!text) throw new Error('Anthropic returned no text content.');
  return { text, stopReason: data.stop_reason ?? null };
}

/**
 * Generate the structured brief, surfacing the run signals.
 * Retries once if the model returns invalid JSON or fails schema
 * validation — the same retry behaviour generateBrief has always
 * had; only the return shape is richer.
 */
export async function generateBriefWithSignals(
  apiKey: string,
  model: string,
  signals: PageSignals,
  detections: Detection[],
  news: NewsItem[],
  seller: SellerProfile | null = null,
  hiring: HiringSignals | null = null,
): Promise<BriefGeneration> {
  if (!apiKey) throw new Error('No Anthropic API key set. Open the extension options to add one.');
  const prompt = buildPrompt(signals, detections, news, seller, hiring);
  // Pre-send ceiling guard: fail loudly by name BEFORE any API
  // call if the assembled prompt plus the output ceiling exceeds
  // the combined ceiling. Nothing is truncated or shortened.
  const promptTokens = estimateTokens(prompt);
  if (promptTokens + BRIEF_MAX_OUTPUT_TOKENS > BRIEF_MAX_TOTAL_TOKENS) {
    throw new Error(
      `prompt-over-ceiling: assembled prompt is ~${promptTokens} tokens; with the ${BRIEF_MAX_OUTPUT_TOKENS}-token output ceiling it exceeds the ${BRIEF_MAX_TOTAL_TOKENS}-token total ceiling. No API call was made.`,
    );
  }
  let lastError: unknown;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const { text, stopReason } = await callAnthropic(apiKey, model, prompt);
      const validation = validateBriefResponse(text);
      if (!validation.valid || !validation.brief) {
        throw new Error(`Invalid brief response: ${validation.failures.join(', ')}`);
      }
      // Stamp the current schema version: the model is not asked
      // for the field (an omitted field parses as legacy 1 and must
      // not fail for that reason alone), but a brief produced by
      // the current code is a version-2 brief.
      const stamped: Brief = {
        ...validation.brief,
        schemaVersion: CURRENT_BRIEF_SCHEMA_VERSION,
      };
      return { brief: stamped, stopReason, validation: { ...validation, brief: stamped } };
    } catch (e) {
      lastError = e;
    }
  }
  throw lastError instanceof Error ? lastError : new Error(String(lastError));
}

/**
 * Generate the structured brief. Retries once if the model returns
 * invalid JSON or fails schema validation.
 */
export async function generateBrief(
  apiKey: string,
  model: string,
  signals: PageSignals,
  detections: Detection[],
  news: NewsItem[],
  seller: SellerProfile | null = null,
  hiring: HiringSignals | null = null,
): Promise<Brief> {
  const { brief } = await generateBriefWithSignals(
    apiKey,
    model,
    signals,
    detections,
    news,
    seller,
    hiring,
  );
  return brief;
}
